<?php
require 'header.php';$threshold=max(1,(int)setting('low_stock_threshold','3'));$stats=[];
foreach(['Products'=>'SELECT COUNT(*) FROM products','Orders'=>'SELECT COUNT(*) FROM orders','Customers'=>'SELECT COUNT(DISTINCT email) FROM customers','Sales total'=>'SELECT COALESCE(SUM(total),0) FROM orders WHERE status NOT IN ("Cancelled","Failed Delivery")','Pending orders'=>'SELECT COUNT(*) FROM orders WHERE status="Pending"','Processing orders'=>'SELECT COUNT(*) FROM orders WHERE status IN ("Processing","Shipped","Out for Delivery")','Delivered orders'=>'SELECT COUNT(*) FROM orders WHERE status IN ("Delivered","Completed")','Low stock'=>'SELECT COUNT(*) FROM products WHERE stock < '.(int)$threshold,'Active flash sales'=>'SELECT COUNT(*) FROM flash_sales WHERE active=1 AND starts_at<=NOW() AND ends_at>NOW()'] as $label=>$sql)$stats[$label]=db()->query($sql)->fetchColumn();
$lowStatement=db()->prepare('SELECT p.id,p.name,p.stock,c.category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.stock < ? ORDER BY p.stock,p.name');$lowStatement->execute([$threshold]);$low=$lowStatement->fetchAll();
db()->prepare('DELETE FROM stock_alerts WHERE product_id IN (SELECT id FROM products WHERE stock>=?)')->execute([$threshold]);$insertAlert=db()->prepare('INSERT IGNORE INTO stock_alerts(product_id,last_quantity) VALUES(?,?)');$readAlert=db()->prepare('SELECT notified_at FROM stock_alerts WHERE product_id=?');$markAlert=db()->prepare('UPDATE stock_alerts SET notified_at=NOW(),last_quantity=? WHERE product_id=?');$mailTo=getenv('COLLINS_M_ADMIN_EMAIL');foreach($low as $product){$insertAlert->execute([$product['id'],$product['stock']]);$readAlert->execute([$product['id']]);if($readAlert->fetchColumn()===null&&$mailTo&&filter_var($mailTo,FILTER_VALIDATE_EMAIL)){$subject='Collins M low stock: '.$product['name'];$body=$product['name'].' has '.$product['stock'].' unit(s) in stock.';$from=getenv('COLLINS_M_FROM_EMAIL');$headers=$from&&filter_var($from,FILTER_VALIDATE_EMAIL)?'From: Collins M <'.$from.'>':'';if(function_exists('mail')&&@mail($mailTo,$subject,$body,$headers))$markAlert->execute([$product['stock'],$product['id']]);}}
$latest=db()->query('SELECT o.order_number,o.total,o.status,o.created_at,c.full_name FROM orders o JOIN customers c ON c.id=o.customer_id ORDER BY o.created_at DESC LIMIT 8')->fetchAll();$chart=db()->query('SELECT DATE(created_at) day,SUM(total) total FROM orders WHERE created_at>=DATE_SUB(CURDATE(),INTERVAL 6 DAY) AND status NOT IN ("Cancelled","Failed Delivery") GROUP BY DATE(created_at) ORDER BY day')->fetchAll();
?><div class="admin-title"><p>OVERVIEW</p><h2>Store dashboard</h2></div><div class="admin-shortcuts"><a href="manage-products.php">Manage Products</a><a href="manage-orders.php">Manage Orders</a><a href="manage-customers.php">Manage Customers</a><a href="flash-sales.php">Flash Sales</a><a href="customize.php">Website Customisation</a></div><div class="stats"><?php foreach($stats as $label=>$value):?><div><span><?=e($label)?></span><strong><?=$label==='Sales total'?money($value):number_format((float)$value)?></strong></div><?php endforeach?></div><section class="admin-panel"><h2>Sales performance · 7 days</h2><div class="sales-bars"><?php $max=max(1,...array_map(fn($x)=>(float)$x['total'],$chart));foreach($chart as $day):?><div><span style="height:<?=max(4,(int)((float)$day['total']/$max*100))?>%" title="<?=money($day['total'])?>"></span><small><?=e(date('D',strtotime($day['day'])))?></small></div><?php endforeach?></div></section><section class="admin-panel"><h2>Low-stock alerts (threshold: <?=$threshold?>)</h2><?php if(!$low):?><p>All products are above the alert threshold.</p><?php else:?><table><thead><tr><th>Product</th><th>Category</th><th>Quantity</th></tr></thead><tbody><?php foreach($low as $p):?><tr><td><?=e($p['name'])?></td><td><?=e($p['category_name']??'—')?></td><td class="stock-warning"><?=$p['stock']?></td></tr><?php endforeach?></tbody></table><?php endif?></section><section class="admin-panel"><h2>Recent orders</h2><table><thead><tr><th>Reference</th><th>Customer</th><th>Total</th><th>Status</th><th>Date</th></tr></thead><tbody><?php foreach($latest as $o):?><tr><td><?=e($o['order_number'])?></td><td><?=e($o['full_name'])?></td><td><?=money($o['total'])?></td><td><?=e($o['status'])?></td><td><?=e($o['created_at'])?></td></tr><?php endforeach?></tbody></table></section><?php require 'footer.php';
